/// <summary>
/// MET_PaymPlusJournalPostAndTransfer
/// Bug 81475: Payment Confirmation File Not Posting
/// </summary>
[ExtensionOf(classStr(CustVendPaymReconciliationPost))]
final class METCustVendPaymReconciliationPost_Extension
{
}

Method.Source:
    /// <summary>
    /// Extend construct for vendor payment use the new class METVendPaymReconciliationPost for Post and Transfer instead of Post
    /// </summary>
    /// <param name = "_ledgerJournalType"></param>
    /// <returns></returns>
    public static CustVendPaymReconciliationPost construct(LedgerJournalType  _ledgerJournalType)
    {
        CustVendPaymReconciliationPost  paymReconciliationPost;

        paymReconciliationPost = next construct(_ledgerJournalType);

        if (_ledgerJournalType == LedgerJournalType::Payment)
        {
            paymReconciliationPost = new METVendPaymReconciliationPost();
        }

        return paymReconciliationPost;
    }
